// scene briefs, legal doctrine §2) run through depth-anything-v2 and a local
// deterministic filmic grade, baked to public/three-d-bg/plates/ (DL13).
// Provenance ledger: notes/verification/shell-wbg/plates-ledger.json
// (prediction ids per stage — I-PROVENANCE). Each entry pairs the depth-
// parallaxed plate with an atmosphere accent so it reads as a SCENE, not a
// wallpaper. Generated by scripts/three-d-backgrounds/gen-wbg-plates.mjs.

import type { BackgroundPreset } from "../types";
import { makePreset, type LayerSpec } from "./build-helpers";

const P = (id: string) => `/three-d-bg/plates/${id}.webp`;
const D = (id: string) => `/three-d-bg/plates/${id}-depth.webp`;

function plateLayer(id: string, z = -46): LayerSpec {
  return {
    suffix: "plate",
    kind: "parallax-plane",
    sourceUrl: P(id),
    depthMapUrl: D(id),
    renderMode: "parallax-plane",
    z,
    parallaxDepth: 0.8,
  };
}

